lemmas.pw-neg-cong:
{C.c : Level} {_≈_.ℓ = _≈_.ℓ₁ : Level} {C : Set C.c}
{_≈_ = _≈₁_ : Rel C _≈_.ℓ₁} {_+_ = f : Op₂ C} {0# = x : C}
{ -_ = x₁ : Op₁ C} →
IsGroup _≈₁_ f x x₁ →
(x₂ g' : A → C) →
liftRel _≈₁_ g g' → liftRel _≈₁_ (lift₁ f' g) (lift₁ f' g')

